const [column, setColumn] = useState<'id' | 'amount'>('amount');
const [direction, setDirection] = useState<'asc' | 'desc'>('desc');

const sortBy = (next: 'id' | 'amount') => {
  if (next === column) {
    setDirection((d) => (d === 'asc' ? 'desc' : 'asc'));
    return;
  }
  setColumn(next);
  setDirection('asc');
};

<Table.Head
  flex={2}
  sortable
  sortDirection={column === 'id' ? direction : undefined}
  onPress={() => sortBy('id')}
>
  Invoice
</Table.Head>

